export type Product={name:string;category:string;type:string;problem:string;mechanism:string;measure:string[];summary:string;applications:string[];benefits:string[];problemTags:string[]};

// The "problem map" a Gujarat Enzyme field-sales guide uses to route a buyer's stated
// problem to the right products, grouped by sector. Product names below must match the
// exact names used in the `make()` calls further down this file.
export type ProblemGroup={sector:string;items:{label:string;productNames:string[]}[]};
export const problemGuide:ProblemGroup[]=[
 {sector:'Dairy & Cattle',items:[
  {label:'Low appetite, indigestion or liver',productNames:['Neoliv']},
  {label:'Energy deficit or ketosis risk',productNames:['NEOBOLITE']},
  {label:'Poor fibre digestion or feed utilisation',productNames:['Myeast','Neobiotic-Rz36CrX','Neobiotic-Rz36Cr','Neobiotic-Rz36Cr Star','NEOBIOTIC','ZYMIX','Rockett']},
  {label:'Low milk yield or low milk fat',productNames:['NEOMILK','Rockett','BooosT','NEOBOLITE']},
  {label:'Calcium or mineral deficiency',productNames:['Spherucal','Neomin 9','Neomin 18','Neovitaz AD3.E']},
  {label:'Mycotoxin risk',productNames:['M-MOS']},
  {label:'Reproductive or uterine issues',productNames:['Utrocent plus Vet.']},
  {label:'Rumen acidosis or heat stress',productNames:['Buffering Start']},
 ]},
 {sector:'Poultry',items:[
  {label:'Poor FCR or feed efficiency',productNames:['EnzyBond','AGX','Phytaaz','POWER PRO ACE']},
  {label:'NSP or high gut viscosity',productNames:['EnzyBond','AGX']},
  {label:'Protein digestion',productNames:['POWER PRO ACE']},
  {label:'Gut health or probiotic support',productNames:['Nutri9','BiomaS','Lysozymex','MUCINZYME']},
  {label:'Mycotoxin risk or immunity',productNames:['M-MOS']},
  {label:'Fly or litter problems',productNames:['LitteraZ']},
 ]},
 {sector:'Aquaculture',items:[
  {label:'Ammonia or nitrite',productNames:['AQUABIOTIC NRB','NITROCLEAN']},
  {label:'Poor water quality or pond ecosystem',productNames:['Aquabiotic','AQUABIOTIC NRB','RHODOKLIN']},
  {label:'Poor digestion or FCR',productNames:['Aquabiotic WS','Myeast AQUA','AQUA PROTEXX']},
  {label:'Liver or feed intake',productNames:['Neoliv Aqua']},
  {label:'Mycotoxin risk',productNames:['M-MOS']},
 ]},
];
const PROBLEM_TAGS:Record<string,string[]>=(()=>{const m:Record<string,string[]>={};problemGuide.forEach(g=>g.items.forEach(it=>it.productNames.forEach(n=>{(m[n]=m[n]||[]).push(it.label)})));return m})();

// Real product data sourced from Gujarat Enzyme catalogues (poultry, dairy & cattle, aquaculture)
// and the client-supplied expert training guide, which adds the mechanism/measurement layer on
// top of the catalogue's stated composition and benefits. Interpretive text (mechanism, what to
// measure) is simplified technical explanation of the catalogue's own claims, not a new claim.
const TECH:Record<string,{problem:string;mechanism:string;measure:string[];summary:string;applications:string[];benefits:string[]}>={
 // ---------- POULTRY ----------
 'EnzyBond':{problem:'Poultry diets contain non-starch polysaccharides, phytate-bound phosphorus and variable protein/fat sources that birds can\u2019t fully break down on their own — capping feed conversion and driving up cost.',mechanism:'Different feed fractions need different enzymes: undigested NSP raises gut viscosity, incomplete protein/starch digestion leaves nutrients unavailable, and phytate binds minerals and phosphorus. EnzyBond\u2019s nine-enzyme blend targets fibre, starch, protein and phytate fractions together.',measure:['FCR','Body-weight gain','Feed intake','Litter condition'],summary:'A multi-enzyme blend (cellulase, xylanase, amylase, phytase, lipase, pectinase, protease, β-glucanase, β-mannanase) formulated to maximise digestibility across the whole diet.',applications:['Broiler and layer feed programs targeting FCR improvement','Diets where feed cost reduction is a priority'],benefits:['Increases digestibility of feedstuff and improves FCR','Increases egg production','Improves bioavailability of carbohydrates, fats, proteins and phosphorus','Optimises NSP and fat digestibility, increasing the ME value of feed','Reduces gut viscosity, ammonia levels and loose droppings']},
 'Nutri9':{problem:'An unstable or underdeveloped gut microbiome in poultry directly shows up as poorer FCR, inconsistent egg quality, and a weaker immune response.',mechanism:'The gut is both a digestive organ and a microbial ecosystem — stable microbial conditions support nutrient utilisation and overall performance, which is why this is built as a synbiotic rather than a straight enzyme product.',measure:['FCR','Body-weight uniformity','Mortality','Egg production, fertility and hatchability in breeders'],summary:'A synbiotic combining nucleotides, two Lactobacillus strains, two Saccharomyces strains and two Bacillus strains — prebiotic and probiotic components formulated to work together.',applications:['Poultry, chicks, grower and layer feed programs','Breeder stock programs targeting fertility and hatchability'],benefits:['Maintains gut microflora and improves digestion','Increases body weight and improves FCR','Maintains egg production, shell quality, fertility and hatchability','Improves livability and uniformity','Stimulates and sustains immune response']},
 'BiomaS':{problem:'Single-strain probiotics don\u2019t cover the full range of gut challenges poultry face across different life stages, from chick to breeder.',mechanism:'A broad multi-strain probiotic consortium matters when the limiting factor is microbial or gut health rather than one feed substrate — pairing ten strains with a five-enzyme profile combines microbial support with digestion support.',measure:['FCR','Growth and uniformity','Mortality','Litter and feed intake'],summary:'A poultry gut-specific probiotic, prebiotic and postbiotic consortium — ten Bacillus, Bifidobacterium and Lactobacillus strains plus MOS and a five-enzyme profile, fortified with B-vitamins.',applications:['Drinking-water or mash-feed gut-health programs across chicks, growers, layers and breeders'],benefits:['Optimises gut health and enhances digestion','Improves nutrient absorption and growth','Improves FCR']},
 'AGX':{problem:'Wheat, rye, barley and triticale-based diets raise gut viscosity because birds lack the enzymes to break down xylan and other plant cell-wall polysaccharides — trapping nutrient value.',mechanism:'Non-starch polysaccharides increase digesta viscosity and physically interfere with nutrient diffusion; xylanase and β-glucanase target the two major NSP fractions directly.',measure:['FCR','Litter moisture','Digestibility response'],summary:'A thermostable xylanase (endo-1,4-β-xylanase) and β-glucanase blend that degrades xylan and other plant cell-wall components, releasing the nutrient value locked in cereal grain endosperm.',applications:['Wheat, rye, barley or triticale-inclusion poultry diets'],benefits:['Gives flexibility in feed formulation','Reduces the negative effects of NSPs in poultry nutrition','Reduces GI tract content viscosity','Improves digestibility and absorption of nutrients, weight gain and feed efficiency']},
 'Phytaaz':{problem:'Most of the phosphorus in grain and oilseed-based poultry diets is locked in phytate and unavailable to the bird — forcing costly inorganic phosphate (DCP/MCP) supplementation.',mechanism:'Phytate binds phosphorus and other nutrients in the diet; phytase hydrolyses phytate to release them, opening room to reformulate the phosphorus matrix of the diet.',measure:['Inorganic phosphorus inclusion rate','Feed cost','Bone quality','Overall performance'],summary:'A micronised phytase enzyme powder (minimum 5,000 FTU/g) that releases phytate-bound phosphorus along with calcium, magnesium, copper, zinc and phytate-bound protein, amino acids and starch.',applications:['Layer and broiler diets aiming to reduce DCP/MCP or bone-meal inclusion'],benefits:['Reduces the supplementation of costly inorganic phosphorus, lowering feed cost','Increases the utilisation and efficiency of minerals, protein and other nutrients','Reduces the overall cost of feed and production']},
 'POWER PRO ACE':{problem:'Lower-cost, harder-to-digest protein sources leave amino acid value on the table and raise nitrogen excretion — a real feed-cost and environmental constraint.',mechanism:'Protein must be hydrolysed into peptides and amino acids before it can be absorbed — undigested protein reaching the distal gut is wasted nutrition and can drive undesirable fermentation.',measure:['FCR','Growth','Nitrogen excretion','Protein cost at reformulated diets'],summary:'A protease (acid and alkaline), cellulase and amylase blend with Lactobacillus sporogenes, protein hydrolysate, amino acids and minerals, built to optimise protein digestion.',applications:['Broiler and layer diets using lower-quality or variable protein sources'],benefits:['Improves protein digestibility and absorption','Allows lower-quality protein sources to be included in feed to manage cost','Improves nutrient absorption by birds','Reduces nitrogen excretion, helping protect the environment']},
 'Lysozymex':{problem:'Antibiotic growth-promoter restrictions have left a gap for natural, residue-free tools that manage bacterial gut challenges without a withdrawal period.',mechanism:'Lysozyme is an antimicrobial enzyme that acts on susceptible bacterial cell-wall structures, giving it activity against both Gram-positive and Gram-negative bacteria without functioning as a conventional antibiotic.',measure:['Gut condition','Mortality','Litter condition','Performance consistency'],summary:'A microbial-origin blend of Lysozyme, Glucose oxidase, Catalase and Vitamin C, produced via GRAS, non-GMO microbial fermentation.',applications:['Gut-health programs seeking an antibiotic-free, residue-free option','Diets where pelleting stability and vitamin/organic-acid compatibility matter'],benefits:['Minimises Gram-positive and Gram-negative bacteria','Residue-free, with no withdrawal period','Improves gut health and natural innate immunity','Stable during pelleting; compatible with vitamins and organic acids']},
 'MUCINZYME':{problem:'Excess or inappropriate mucus and respiratory inflammation in dense poultry housing quietly drag down performance and can increase reliance on antibiotics.',mechanism:'The intestinal mucus layer is functional, but excess mucin can raise viscosity, encourage bacterial adherence and interfere with nutrient absorption — the protease blend is designed to reduce mucin-layer thickness and improve the gut environment.',measure:['Litter condition','Feed conversion','Gut condition','Nutrient-absorption performance'],summary:'A mucinase and proteolytic enzyme blend that hydrolyses inappropriate or excess mucus, targeting the gel layer (MUC5AC/MUC5B) and periciliary layer of the respiratory mucosa, active at the pH 4–6 range of the poultry gut.',applications:['Respiratory-health support programs, especially in high-density housing'],benefits:['Breaks down mucin and reduces viscosity','Enhances mucociliary clearance, reducing mucus accumulation and associated health issues','Supports respiratory health, performance and immune function','May reduce antibiotic usage']},
 'LitteraZ':{problem:'Poultry house litter buildup breeds houseflies and releases ammonia and H2S — a welfare, odour and biosecurity problem that\u2019s hard to manage with a general disinfectant.',mechanism:'Accumulated organic litter provides substrate for insects and odour-forming processes — this is applied to the litter itself rather than through the feed.',measure:['Fly count','Litter moisture and condition','Odour and ammonia/H2S levels'],summary:'A biotech, non-toxic enzyme dusting powder for poultry litter, designed to control houseflies and speed up in-situ litter composting.',applications:['Litter bed treatment in broiler and layer houses'],benefits:['Minimises fly menace (both adult and larvae)','Drives complete litter decomposition and improves litter nutritional value','Minimises litter odour from ammonia and H2S']},
 // ---------- DAIRY & CATTLE ----------
 'Neoliv':{problem:'Liver stress in dairy animals — often around calving or on high-production diets — shows up as reduced appetite, poor digestion and dropping milk output.',mechanism:'Poor intake and digestive disturbance reduce how much usable substrate reaches productive metabolism, and liver dysfunction can further compromise normal metabolic processing.',measure:['Feed intake','Rumination','Dung consistency','Milk yield'],summary:'A liver tonic built on tricholine citrate, choline chloride, sorbitol, nicotinamide, ferric ammonium citrate, inositol and Vitamin B12, with a base fortified with crude liver extract.',applications:['Anorexia, indigestion and liver-disorder cases in cattle, horses and dogs'],benefits:['Increases appetite and improves digestion','Improves milk production','Corrects liver disorder and improves overall health']},
 'NEOBOLITE':{problem:'Around calving, dairy cows face a severe energy deficit that can trigger ketosis and fatty liver — directly hitting milk yield.',mechanism:'Early lactation can open a gap between energy intake and energy demand; glucogenic precursors support glucose/energy availability while choline-related nutrients support hepatic lipid metabolism.',measure:['Milk yield','Appetite','Body-condition trend','Ketosis indicators where available'],summary:'An energy-booster with liver-tonic action, combining gluconeogenic precursors, choline sources, B-vitamins, Vitamin C, folic acid and tri sodium citrate.',applications:['Early post-calving support for cows and buffaloes returning to feed'],benefits:['Helps bring the animal back to feed and optimum milk production','Helps prevent ketosis and protects against fatty liver','Improves availability of energy and FCR','Maintains udder/teat health and milk pH']},
 'Myeast':{problem:'Inconsistent dry matter intake and rumen fermentation efficiency limit how much energy and microbial protein an animal can actually extract from its feed.',mechanism:'Ruminants depend on microbial fermentation to extract energy from fibre — if fibre digestion is inefficient, part of the ration\u2019s potential energy passes through unconverted.',measure:['Dry matter intake','Dung fibre','Milk yield and fat trend','Rumination'],summary:'A yeast product that ferments a wide range of carbohydrates and sugars, producing ethanol and CO2 as metabolites, and supplying B-vitamins and trace minerals.',applications:['Rumen fermentation support across cattle diets'],benefits:['Stimulates digestive microflora, positively affecting dry matter intake, rumen pH and nutrient digestibility','Enhances cellulolytic (fibre-digesting) bacteria, increasing the rate and efficiency of ruminal fermentation','Increases feed intake and microbial protein, extracting more energy from feedstuffs']},
 'Neobiotic-Rz36CrX':{problem:'Poor feed conversion and inconsistent milk components (SNF/fat) often trace back to viscous, poorly digested feed and gut microbial imbalance in cattle.',mechanism:'A ration loses efficiency when microbial support, enzyme activity and feed viscosity all limit nutrient release at once — combining organic chromium, live yeast, probiotics and three enzymes addresses several bottlenecks simultaneously rather than one. This is the organic-base carrier variant of the Rz36 range.',measure:['Dry matter intake','FCR / feed efficiency','Milk yield','Dung consistency'],summary:'The organic-base variant of the Rz36 range — organic chromium, Saccharomyces cerevisiae, Lactobacillus sporogenes, fermented live yeast culture, MOS+β-glucan and a cellulase/amylase/xylanase enzyme blend, on an organic carrier.',applications:['Cattle feed formulation targeting milk yield and composition'],benefits:['Improves dry matter intake and decreases feed viscosity','Enhances digestion of feed and fibre','Improves milk production, SNF and FAT percentage','Better utilisation of non-starch polysaccharides']},
 'Neobiotic-Rz36Cr':{problem:'Poor feed conversion and inconsistent milk components (SNF/fat) often trace back to viscous, poorly digested feed and gut microbial imbalance in cattle.',mechanism:'A ration loses efficiency when microbial support, enzyme activity and feed viscosity all limit nutrient release at once — combining organic chromium, live yeast, probiotics and three enzymes addresses several bottlenecks simultaneously rather than one. This is the inorganic-base carrier variant of the Rz36 range.',measure:['Dry matter intake','FCR / feed efficiency','Milk yield','Dung consistency'],summary:'The inorganic-base variant of the Rz36 range — the same organic chromium, yeast culture, Lactobacillus sporogenes, MOS+β-glucan and enzyme blend, on an inorganic carrier.',applications:['Cattle feed formulation targeting milk yield and composition'],benefits:['Improves dry matter intake and decreases feed viscosity','Enhances digestion of feed and fibre','Improves milk production, SNF and FAT percentage','Better utilisation of non-starch polysaccharides']},
 'Neobiotic-Rz36Cr Star':{problem:'Poor feed conversion and inconsistent milk components (SNF/fat) often trace back to viscous, poorly digested feed and gut microbial imbalance in cattle.',mechanism:'The same multi-pathway concept as the rest of the Rz36 range — microbial balance plus enzymatic support for feed utilisation, most relevant when the problem is broad inefficiency rather than a single nutrient gap.',measure:['Dry matter intake','FCR / feed efficiency','Milk yield','Dung consistency'],summary:'The starch-base variant of the Rz36 range — the same organic chromium, yeast culture, Lactobacillus sporogenes, MOS+β-glucan and enzyme blend, on a starch carrier.',applications:['Cattle feed formulation targeting milk yield and composition'],benefits:['Improves dry matter intake and decreases feed viscosity','Enhances digestion of feed and fibre','Improves milk production, SNF and FAT percentage','Better utilisation of non-starch polysaccharides']},
 'Spherucal':{problem:'Calcium deficiency around calving is a leading cause of milk fever and uterine prolapse in dairy cattle.',mechanism:'Calcium is required for neuromuscular function, bone metabolism and milk secretion; Vitamin D3 supports the calcium absorption and homeostasis that determine whether dietary calcium is actually usable by the animal.',measure:['Blood calcium level where tested','Production response','Calving-window risk signs'],summary:'An organic calcium source built on Microcrystalline Hydroxyapatite Complex (MCHC), providing calcium, phosphorus, Vitamin D3, Vitamin B12, magnesium and manganese.',applications:['Pregnant and milch animal calcium support'],benefits:['Improves milk quality and quantity','Improves blood calcium level of pregnant and milch animals','Minimises calcium-deficiency disorders like milk fever, uterine prolapse and ruminal stress']},
 'NEOMILK':{problem:'Repeat-breeder cows and animals recovering from antibiotic therapy often show poor conception rates and irregular heat cycles alongside lower milk output.',mechanism:'Milk production depends on energy, protein, minerals, digestion and health together — this is positioned as a broad supportive formulation rather than a single-nutrient correction.',measure:['Milk litres/day','Milk fat %','Body condition','Reproductive performance'],summary:'A milk-booster formula blending herbs and synthetic ingredients, fortified with an energy source and minerals.',applications:['Repeat-breeder and post-antibiotic-therapy reproductive support'],benefits:['Improves milk yield and FAT percentage','Minimises residual effects of antibiotic therapy','Helps improve conception ratio for repeat breeders and induces/regulates heat periods','Improves reproductive performance and nutritional status']},
 'NEOBIOTIC':{problem:'Poor NSP digestibility and gut viscosity quietly raise feed cost per unit of milk produced.',mechanism:'Protein and carbohydrate only become useful once digestion releases their absorbable components, and viscosity can interfere with that process — MOS, live cultures and cellulase work the microbial and enzymatic sides of that problem together.',measure:['Feed intake','Dung consistency','Milk yield','Feed efficiency'],summary:'A synbiotic with minerals — MOS+β-glucan, fermented live yeast culture, Saccharomyces cerevisiae, two Bacillus strains, plus calcium, phosphorus, zinc, manganese and copper.',applications:['General cattle, sheep and goat feed formulation'],benefits:['Improves bioavailability of carbohydrate and protein','Optimises digestibility of non-starch polysaccharides','Delivers feed cost savings and reduces gut viscosity']},
 'ZYMIX':{problem:'Non-starch polysaccharides in cattle feed limit nutrient uptake and cap milk fat percentage and yield.',mechanism:'Structural carbohydrates in fibre and NSP limit nutrient release and can raise viscosity — targeted enzymatic breakdown of cellulose, xylan, starch and phytate increases the fraction of nutrients actually accessible to digestion.',measure:['Milk yield and fat','Feed intake','Dung fibre','Feed cost per litre'],summary:'A fibrolytic multi-enzyme blend (cellulase, xylanase, amylase, pectinase, phytase) powered by essential trace minerals (cobalt, copper, zinc and ferrous sulphate).',applications:['Cattle feed formulation targeting milk yield and FCR'],benefits:['Better utilisation of non-starch polysaccharides','Better milk fat percentage and milk yield','Decreases feed viscosity and maximises nutrient uptake','Better feed conversion ratio']},
 'Neomin 9':{problem:'A gap in vitamin and trace-mineral status in cattle diets shows up as poor calf growth, stress sensitivity and lower fertility or milk output.',mechanism:'Micronutrient deficiencies rarely produce one obvious symptom — they show up as reduced growth, fertility, immunity or production, which is why a broad premix is built to cover multiple requirements at once rather than one.',measure:['Growth','Fertility','Milk production','Body condition'],summary:'A vitamin and mineral premix (Vitamins A, D3, B2, B12, E, calcium D-pantothenate, biotin, plus calcium, phosphorus and a full trace-mineral profile), fortified with Jivanti and Shatavari herbs and antioxidants.',applications:['Baseline vitamin/mineral fortification for calves, heifers and lactating cattle'],benefits:['Optimises growth and health of calves and heifers','Alleviates stress and related disorders','Enhances immunity and fertility','Boosts milk production of lactating animals']},
 'Neomin 18':{problem:'A gap in vitamin and trace-mineral status in cattle diets shows up as poor calf growth, stress sensitivity and lower fertility or milk output.',mechanism:'Like other broad premixes, its role is covering multiple micronutrient requirements that underpin production and reproduction — nutritional infrastructure rather than a fix for an unrelated problem.',measure:['Growth','Fertility','Milk production','Body condition'],summary:'An expanded vitamin and mineral premix (Vitamins A, D3, E, B12, B2, calcium D-pantothenate, biotin, plus an 11-element mineral profile including iodine and sulphur), with a Shatavari and Jivanti herbal profile.',applications:['Baseline vitamin/mineral fortification for calves, heifers and lactating cattle'],benefits:['Optimises growth and health of calves and heifers','Alleviates stress and related disorders','Enhances immunity and fertility','Boosts milk production of lactating animals']},
 'Rockett':{problem:'Picky eaters and off-feed cattle — common after stress, illness or a feed change — need a palatability and digestion boost to get back to normal intake and milk output.',mechanism:'Reduced intake directly limits available nutrients, and poor fibre digestion further reduces energy extraction — yeast, probiotic, enzyme and appetite-supporting herbs are combined to address both ends of that chain together.',measure:['Feed intake','Rumination','Dung fibre','Milk litres and fat'],summary:'A yeast, probiotic and enzyme blend (40% Saccharomyces cerevisiae, Lactobacillus sporogenes, cellulase/amylase/xylanase) with a 20% herbal profile of ginger, black pepper, long pepper, rock salt, black salt, pomegranate and ajwain.',applications:['Appetite and intake support for cattle coming off feed'],benefits:['Works as a natural, strong appetiser','Improves digestion of feed and fibre','Improves milk production and SNF/FAT percentage','Improves utilisation of non-starch polysaccharides and nutrient availability']},
 'Neovitaz AD3.E':{problem:'A gap in fat-soluble vitamin status shows up quietly — as weaker immunity, poorer bone mineralisation, reduced antioxidant defence and thinner milk.',mechanism:'Vitamins A, D3 and E each support distinct physiological functions, with D3 specifically relevant to calcium homeostasis and reproductive and udder condition.',measure:['Dietary vitamin supply','Reproductive performance','Milk quality','Calcium-related risk'],summary:'A fat-soluble vitamin premix built on Vitamin A, D3 and E on an organic-matter base.',applications:['Baseline vitamin fortification across poultry, dairy and livestock diets'],benefits:['Supports thick, creamy milk and increased milk production','Supports better growth, productivity and reproductive performance','Boosts immunity and optimises skin coat condition and calcium absorption']},
 'Utrocent plus Vet.':{problem:'Incomplete uterine involution after calving delays the return to normal reproductive cycling and can leave discharge unresolved.',mechanism:'Normal uterine involution and reproductive recovery after calving directly affect the interval to the next successful conception.',measure:['Post-calving discharge','Uterine involution','Return to normal reproductive cycling'],summary:'An herbal formulation of Gokharu, Shatavari, Klonji, Hirabol, Chitrak, Manjishtha and Lodhar.',applications:['Post-calving uterine health support in cattle, buffalo, sheep, goats and horses'],benefits:['Helps keep the uterus clean and promotes uterine involution','Helps the next reproduction cycle onset normally','Helps control vaginal discharge']},
 'Buffering Start':{problem:'Ruminal acidosis and heat stress panting are common, costly disruptions in intensive cattle and buffalo operations.',mechanism:'A high fermentable-carbohydrate load increases ruminal acid production; when buffering capacity and rumen adaptation are inadequate, rumen pH can fall and both fibre digestion and rumen function suffer.',measure:['Rumination and cud chewing','Feed intake','Dung consistency','Ration starch/concentrate load'],summary:'A rumen buffer fortified with yeast, indicated for ruminal acidosis, laminitis and panting under heat stress.',applications:['Short-course rumen-stability support during acidosis, laminitis or heat-stress episodes'],benefits:['Targets ruminal acidosis and laminitis','Supports animals panting under heat stress']},
 'BooosT':{problem:'Depressed feed intake directly caps milk yield, whatever else is right about the ration.',mechanism:'When intake falls, the animal receives less energy, protein and micronutrients, which quickly shows up as lower milk output.',measure:['Dry matter intake','Milk yield','Appetite','Body condition'],summary:'A live yeast culture, prebiotic/probiotic and amino acid blend.',applications:['General feed-intake and milk-yield support'],benefits:['Boosts up feed intake','Improves milk yield']},
 // ---------- AQUACULTURE ----------
 'Aquabiotic':{problem:'Pond bottoms accumulate organic waste and uneaten feed that degrade water quality and stress stocked animals.',mechanism:'Organic residues in the pond become substrate for microbial activity and contribute to oxygen demand and nitrogenous waste; Bacillus organisms paired with a four-enzyme profile support beneficial microbial degradation of that load.',measure:['Ammonia and nitrite','Dissolved oxygen','Water colour and organic load'],summary:'A pond-management blend of four Bacillus probiotic strains and a five-enzyme profile (protease, amylase, cellulase, xylanase, β-glucanase).',applications:['Shrimp pond preparation and ongoing pond management','Fish and other aquaculture species pond maintenance'],benefits:['Degrades organic waste and litter, improving the pond environment','Thermostable, broad-spectrum, eco-friendly and biodegradable','Non-pathogenic with specific, targeted action']},
 'Aquabiotic WS':{problem:'Loose-shell syndrome and poor FCR in shrimp and prawn farming often trace back to inadequate protein and phosphorus digestion in the gut.',mechanism:'Shrimp and fish growth depends on digestion, absorption and a stable intestinal microbial environment — probiotics, yeast and a five-enzyme profile are combined to support all three at once.',measure:['FCR','Growth','Feed response and wastage','Survival'],summary:'A feed probiotic combining four probiotic strains, Saccharomyces cerevisiae yeast, a six-enzyme profile (amylase, phytase, protease, cellulase, beta-galactosidase, lipase) and a vitamin profile.',applications:['Shrimp, prawn and fish feed supplementation'],benefits:['Improves digestive system efficiency and nutrient absorption/synthesis','Phytase improves phosphorus availability; protease improves digestion of proteinaceous material','Multi-enzyme action helps check loose-shell problems','Improves FCR, growth rate and weight gain']},
 'Myeast AQUA':{problem:'Frequent water exchange and stress-related infection susceptibility are recurring costs in intensive aquaculture.',mechanism:'Stress can suppress feeding and compromise intestinal function; yeast fermentation metabolites are used to support intestinal integrity and resistance to infection under stress.',measure:['Feed intake','FCR','Growth','Performance around stress events'],summary:'The aquaculture application of Myeast — fermenting carbohydrates and sugars to produce metabolites and B-vitamins that support gut and pond ecosystem stability.',applications:['Shrimp, prawn and fish feed supplementation'],benefits:['Reduces water exchange needs and enhances the aquatic ecosystem','Maintains intestinal integrity and improves resistance to infection under stress','Improves growth performance and FCR']},
 'AQUABIOTIC NRB':{problem:'Ammonia and nitrite buildup from uneaten feed and waste is directly toxic to stocked fish and shrimp, and poor algal balance destabilises the whole pond.',mechanism:'Ammonia and nitrite are the key nitrogen compounds in intensive aquaculture; Nitrosomonas and Nitrobacter drive the biological nitrification pathway that converts them into less toxic forms, while Rhodococcus and Bacillus broaden the ecosystem support.',measure:['Ammonia-N and nitrite-N','pH, dissolved oxygen and alkalinity','Stocking density and feeding rate'],summary:'A pond-ecosystem blend of nitrifying bacteria (Nitrosomonas sp. and Nitrobacter), photosynthetic bacteria (Rhodococcus sp. and Rhodobacter) and five Bacillus species.',applications:['Pond preparation and ongoing water-quality management for shrimp and fish'],benefits:['Improves soil and water quality and reduces toxic ammonia and nitrites','Enhances degradation of organic waste and helps balance pond ecology','Develops and stabilises a good algal bloom; prevents vibrio occurrence','Effective across pH 5.0–9.8 and salinity 0–50ppm']},
 'NITROCLEAN':{problem:'Ammonia and nitrite buildup from uneaten feed and waste is directly toxic to stocked fish and shrimp.',mechanism:'Nitrosomonas and Nitrobacter are the central nitrifying organisms in the pond nitrogen cycle, making this a targeted response to ammonia/nitrite accumulation specifically rather than a general pond-quality product.',measure:['Ammonia and nitrite readings','pH and dissolved oxygen','Culture age'],summary:'A pond-ecosystem blend of nitrifying bacteria — Nitrosomonas sp. and Nitrobacter — with five Bacillus species, that convert toxic nitrogen compounds into less harmful forms.',applications:['Ongoing aquaculture pond water-quality management'],benefits:['Reduces ammonia and nitrite levels in pond water','Effective across a wide range of pond conditions when applied on a regular interval']},
 'RHODOKLIN':{problem:'Unstable pond ecology and poor organic-waste turnover reduce the water quality stocked animals depend on.',mechanism:'Not every pond problem is ammonia alone — broader microbial and organic-load imbalance can also destabilise the system, which is what this Rhodococcus/Bacillus blend is built to support.',measure:['Water quality and organic load','Ammonia/nitrite as a comparison point','Pond stability'],summary:'A pond-ecosystem blend of photosynthetic bacteria — Rhodococcus sp. and Rhodobacter sp. — with five Bacillus species.',applications:['Ongoing aquaculture pond ecosystem management'],benefits:['Supports pond ecosystem balance alongside the nitrifying-bacteria products in the range']},
 'AQUA PROTEXX':{problem:'Shrimp and prawn growth performance depends on gut digestive efficiency that a single probiotic strain often can\u2019t deliver alone.',mechanism:'Feed conversion depends on how efficiently feed is digested into absorbable nutrients — a combined probiotic, yeast and five-enzyme system supports that pathway directly, distinct from a water-chemistry fix.',measure:['FCR','Growth','Feed intake and wastage','Survival'],summary:'A multistrain probiotic (six genera including Bacillus, Lactobacillus, Enterococcus, Streptococcus, Pediococcus and Clostridium butyricum) with yeast and a five-enzyme profile, built for multiple protection.',applications:['Shrimp and prawn feed supplementation'],benefits:['Improves digestive system efficiency and nutrient absorption/synthesis','Phytase improves phosphorus availability; protease improves digestion of proteinaceous material','Improves FCR, growth rate and weight gain']},
 'Neoliv Aqua':{problem:'Hepatopancreas stress in shrimp and prawns from intensive feeding directly reduces growth and feed conversion.',mechanism:'Poor appetite and digestion reduce nutrient intake and utilisation in shrimp and fish just as in livestock — the formulation ties liver support directly to feed intake and conversion.',measure:['Feed intake','FCR','Feed wastage','Growth and survival'],summary:'A liver tonic for aquaculture species built on tricholine citrate, choline chloride, sorbitol, nicotinamide, ferric ammonium citrate, inositol and Vitamin B12 — no antibiotics, no side effects.',applications:['Indigestion and liver-disorder support in prawns, shrimp and fish'],benefits:['Improves liver function and reduces fat deposition','Improves FCR and weight gain; strengthens hepatopancreas function in prawns','Enhances neurological and hormonal function; speeds up healing; supports muscle and skeletal strength']},
 // ---------- Shared / cross-category real ingredients ----------
 'M-MOS':{problem:'Mycotoxin contamination and pathogen pressure in feed silently reduce immunity, growth and, in aquaculture, survival rates.',mechanism:'Feed-borne mycotoxins can impair performance and immune defence even when the visible symptom is simply reduced growth — MOS from yeast cell walls provides a toxin-binding and functional gut-support component.',measure:['Feed storage and mould risk','Growth/FCR','Mortality or unexplained performance loss'],summary:'A prebiotic derived from the cell wall of Saccharomyces cerevisiae yeast, rich in mannan oligosaccharides and β-glucans.',applications:['Poultry, cattle and aquaculture feed programs targeting immune support'],benefits:['Improves immunity and animal performance','Binds mycotoxins (notably zearalenone)','Reduces mortality']},
 // ---------- Well-established standalone actives (Enzymes / Probiotics & Prebiotics categories) ----------
 'Amylase':{problem:'Cereal-based diets don\u2019t always release their full starch energy — especially in young animals whose own amylase output is still developing.',mechanism:'An α-amylase hydrolyses the α-1,4 glycosidic bonds in starch, breaking it down into shorter dextrins and fermentable sugars.',measure:['Starch digestibility','Energy availability from the diet'],summary:'An α-amylase that hydrolyses the α-1,4 glycosidic bonds in starch, breaking it down into shorter dextrins and fermentable sugars.',applications:['Cereal-based broiler and layer diets','Young-animal diets where endogenous amylase secretion is still developing'],benefits:['Improves starch digestibility and energy availability from the diet','Reduces variability in raw-material starch quality across batches']},
 'Beta Galactosidase':{problem:'Young calves and piglets can\u2019t yet digest lactose efficiently, risking scours and wasted milk-replacer nutrition.',mechanism:'A β-galactosidase (lactase) hydrolyses lactose into glucose and galactose.',measure:['Scour incidence in young stock','Milk-replacer utilisation'],summary:'A β-galactosidase (lactase) that hydrolyses lactose into glucose and galactose.',applications:['Milk-replacer formulations for calves and piglets','Dairy-adjacent feed applications with residual lactose'],benefits:['Supports lactose digestion in animals with limited native lactase activity','Reduces the risk of undigested-lactose-driven scouring in young stock']},
 'Beta Glucanase':{problem:'Barley- and oat-based diets thicken in the gut, trapping nutrients and leading to wet, sticky droppings.',mechanism:'Breaks down β-glucans — non-starch polysaccharides concentrated in barley and oats — that otherwise raise digesta viscosity.',measure:['Litter/manure moisture','Digesta viscosity'],summary:'Breaks down β-glucans — non-starch polysaccharides concentrated in barley and oats — that otherwise raise digesta viscosity.',applications:['Barley- or oat-inclusion poultry and swine diets','High-viscosity NSP diets prone to sticky droppings'],benefits:['Lowers intestinal digesta viscosity for better nutrient contact and absorption','Reduces litter/manure moisture issues linked to viscous digesta']},
 'Mannanase':{problem:'Soybean meal and palm kernel meal contain mannans that trigger a costly immune response, quietly eating into feed efficiency.',mechanism:'A β-mannanase hydrolyses mannan-based polysaccharides found in soybean meal and palm kernel meal, reducing their anti-nutritional load.',measure:['FCR','Immune-response indicators'],summary:'A β-mannanase that hydrolyses mannan-based polysaccharides found in soybean meal and palm kernel meal.',applications:['Soybean meal or palm kernel meal-based diets','Programs targeting feed-conversion efficiency'],benefits:['Reduces the anti-nutritional load of dietary mannans','Can spare the metabolic cost of the immune response mannans otherwise trigger']},
 'Bromelain':{problem:'Lower-cost protein sources are often harder to digest, leaving amino acid value on the table.',mechanism:'A cysteine protease derived from pineapple stem hydrolyses proteins into peptides and free amino acids.',measure:['Protein digestibility','Amino acid availability'],summary:'A cysteine protease derived from pineapple stem that hydrolyses proteins into peptides and free amino acids.',applications:['Protein digestibility programs','Feed formulations using lower-cost, harder-to-digest protein sources'],benefits:['Improves breakdown of dietary protein ahead of absorption','Supports amino acid availability from varied protein sources']},
 'Catalase':{problem:'Peroxide residues in processed feed ingredients can compromise feed quality and put oxidative stress on the animal.',mechanism:'An antioxidant enzyme decomposes hydrogen peroxide into water and oxygen.',measure:['Peroxide load in processed ingredients'],summary:'An antioxidant enzyme that decomposes hydrogen peroxide into water and oxygen.',applications:['Feed and process streams where peroxide residues need to be managed','Oxidative-stress-sensitive formulations'],benefits:['Helps manage peroxide load in processed feed ingredients','Complements broader oxidative-stability strategies']},
 'Cellulase':{problem:'Fibrous, by-product-heavy diets lock nutrients inside plant cell walls that the animal can\u2019t break open on its own.',mechanism:'Breaks down cellulose — the β-1,4-glucan backbone of plant cell walls — releasing nutrients otherwise trapped inside fibrous material.',measure:['Feeding value of fibrous raw materials','Digestibility'],summary:'Breaks down cellulose — the β-1,4-glucan backbone of plant cell walls — releasing nutrients otherwise trapped inside fibrous material.',applications:['High-fibre or by-product-inclusion diets','Ruminant and monogastric diets with significant plant fibre content'],benefits:['Unlocks nutrients bound within plant cell-wall structures','Improves the feeding value of fibrous raw materials']},
 'Lipase':{problem:'Young animals can\u2019t fully digest dietary fat, wasting one of the densest energy sources in the diet.',mechanism:'Hydrolyses dietary triglycerides into free fatty acids and glycerol.',measure:['Fat digestibility, particularly in young animals'],summary:'Hydrolyses dietary triglycerides into free fatty acids and glycerol.',applications:['High-fat diets and young-animal starter feeds','Diets for species/stages with limited pancreatic lipase output'],benefits:['Improves fat digestibility, particularly in young animals','Supports energy utilisation from added dietary fats and oils']},
 'Phytase':{problem:'Most of the phosphorus in grain and oilseed diets is chemically locked in phytate and unavailable to poultry, swine or fish — forcing costly inorganic phosphate supplementation and excess phosphorus in manure.',mechanism:'Hydrolyses phytate — the storage form of phosphorus in plant seeds — releasing bound phosphorus for absorption.',measure:['Inorganic phosphate inclusion rate','Phosphorus excretion'],summary:'Hydrolyses phytate — the storage form of phosphorus in plant seeds — releasing bound phosphorus for absorption.',applications:['Grain- and oilseed-meal-based diets across poultry, swine and aquaculture','Formulations aiming to reduce inorganic phosphate inclusion'],benefits:['Reduces dependence on inorganic phosphate supplementation','Lowers phosphorus excretion, supporting environmental compliance goals','Can improve availability of phytate-bound minerals and amino acids']},
 'Protease':{problem:'Variable-quality protein sources reduce amino acid digestibility, driving up feed cost for every unit of growth.',mechanism:'Hydrolyses peptide bonds in dietary protein, breaking it down into peptides and free amino acids.',measure:['Protein/amino acid digestibility','Nitrogen excretion'],summary:'Hydrolyses peptide bonds in dietary protein, breaking it down into peptides and free amino acids.',applications:['Formulations targeting reduced crude protein without a performance trade-off','Diets using variable-quality protein sources'],benefits:['Improves protein and amino acid digestibility','Supports lower dietary nitrogen excretion at matched performance']},
 'Xylanase':{problem:'Wheat- and rye-based diets raise gut viscosity, slowing nutrient absorption and hurting feed conversion.',mechanism:'A non-starch polysaccharide (NSP) enzyme hydrolyses arabinoxylans, the viscosity-raising fibre fraction in wheat, rye and barley.',measure:['Digesta viscosity','FCR'],summary:'A non-starch polysaccharide (NSP) enzyme that hydrolyses arabinoxylans, the viscosity-raising fibre fraction in wheat, rye and barley.',applications:['Wheat- or rye-based poultry and swine diets','Diets formulated alongside other NSP enzymes'],benefits:['Reduces digesta viscosity for improved nutrient access','Commonly paired with β-glucanase in cereal-heavy formulations']},
 'Serratiopeptidase':{problem:'Mucosal and respiratory stress in intensive production systems can quietly erode comfort and performance.',mechanism:'A proteolytic enzyme referenced for its mucolytic and anti-inflammatory associations alongside general proteolytic activity.',measure:['Respiratory/mucosal comfort indicators'],summary:'A proteolytic enzyme referenced in animal-health contexts for its mucolytic and anti-inflammatory associations alongside general proteolytic activity.',applications:['Supportive formulations targeting mucosal and respiratory comfort'],benefits:['Contributes proteolytic activity alongside its mucolytic association','Used as a supporting component in targeted health formulations']},
 // ---------- Bacterial cultures (full Gujarat Enzyme strain library) ----------
 'Bacillus amyloliquefaciens':{problem:'Diets with intact starch and protein fractions leave energy and amino acids unavailable when the gut\u2019s own enzymatic capacity is limited.',mechanism:'A spore-forming Bacillus species that produces its own amylase and protease enzymes as it establishes in the gut, supplementing the animal\u2019s native digestive enzyme activity.',measure:['Feed conversion','Gut microbial balance','Growth rate'],summary:'A spore-forming probiotic Bacillus species valued for its native amylase and protease enzyme production alongside standard probiotic gut-colonisation benefits.',applications:['Heat-processed feed probiotic programs across poultry, livestock and aquaculture'],benefits:['Survives pelleting heat as a spore, then germinates in the gut','Contributes native amylase and protease activity alongside gut colonisation','Supports competitive exclusion of pathogenic bacteria']},
 'Bacillus cereus':{problem:'Some feed programs still rely on non-spore probiotics that don\u2019t survive processing heat or a variable gut pH.',mechanism:'A spore-forming Bacillus species; the resistant spore form survives pelleting and gastric transit before germinating in the intestine, similar to other Bacillus probiotics in this range.',measure:['Gut colonisation post-processing','Pathogen pressure'],summary:'A spore-forming Bacillus species used as a heat- and acid-tolerant probiotic component in animal feed formulations.',applications:['Feed probiotic blends where processing survival is a priority'],benefits:['Withstands feed manufacturing heat and low gastric pH as a spore','Germinates in the gut to contribute to a balanced microbial population']},
 'Bacillus clausii':{problem:'Antimicrobial use in production animals can disrupt the existing gut microbial population, leaving a temporary gap in colonisation resistance.',mechanism:'A spore-forming, naturally antibiotic-tolerant Bacillus species often used where gut microbial support is needed alongside or around antimicrobial use.',measure:['Gut microbial recovery','Digestive comfort indicators'],summary:'A spore-forming Bacillus species noted for natural tolerance to several antibiotic classes, used as a gut-support probiotic.',applications:['Gut microbiota support programs, including around antimicrobial treatment periods'],benefits:['Spore form withstands feed processing and gastric transit','Natural antibiotic tolerance supports use alongside certain treatment programs','Contributes to gut microbial balance']},
 'Bacillus coagulans':{problem:'Standard lactic-acid bacteria are heat-sensitive and often don\u2019t survive feed pelleting, limiting their usefulness in processed feed.',mechanism:'A spore-forming, lactic-acid-producing Bacillus species that combines the heat tolerance of a Bacillus spore with the acid-producing action typical of Lactobacillus species.',measure:['Gut pH stability','Feed processing survival','Digestive performance'],summary:'A spore-forming Bacillus species that produces lactic acid, giving it both the pelleting-heat tolerance of a Bacillus spore and the acid-producing probiotic action typical of Lactobacillus.',applications:['Heat-processed feed programs needing a lactic-acid-producing probiotic'],benefits:['Survives feed pelleting as a heat-resistant spore','Produces lactic acid to help stabilise gut pH','Combines probiotic action with processing durability']},
 'Bacillus firmus':{problem:'Feed and litter organic-matter buildup and inconsistent gut microbial balance both benefit from a hardy, broadly adapted Bacillus strain.',mechanism:'A spore-forming soil and gut Bacillus species used as a general-purpose probiotic and, in some formulations, for its role supporting organic-matter breakdown.',measure:['Gut microbial balance','Organic-matter turnover where applicable'],summary:'A spore-forming Bacillus species used as a general probiotic component, also associated with organic-matter degradation in some agricultural and litter applications.',applications:['General-purpose Bacillus probiotic blends'],benefits:['Survives processing and gastric transit as a spore','Broadly adapted for gut and, in some uses, litter/soil applications']},
 'Bacillus licheniformis':{problem:'Poultry and livestock diets need a probiotic that survives processing and actively contributes enzymatic support once established in the gut.',mechanism:'A widely used spore-forming Bacillus species that produces its own protease and other enzymes, commonly paired with B. subtilis in commercial probiotic blends.',measure:['FCR','Gut microbial balance','Growth performance'],summary:'A spore-forming Bacillus species, one of the most widely used commercial probiotic strains, known for protease production alongside standard gut-support action.',applications:['Poultry, livestock and aquaculture probiotic feed programs'],benefits:['Survives feed pelleting heat and gastric transit as a spore','Contributes native protease activity','Widely validated as a commercial gut-health probiotic strain']},
 'Bacillus megaterium':{problem:'Gut microbial balance and, in agricultural applications, phosphorus availability in soil both benefit from a hardy Bacillus strain.',mechanism:'A spore-forming Bacillus species recognised for phosphate-solubilising activity in agricultural contexts and general probiotic gut support in animal feed.',measure:['Gut microbial balance','Phosphorus availability where used agriculturally'],summary:'A spore-forming Bacillus species used as a general probiotic in animal feed and recognised in agriculture for phosphate-solubilising activity.',applications:['General Bacillus probiotic blends'],benefits:['Survives processing and gastric transit as a spore','Contributes to gut microbial balance','Associated with phosphate-solubilising activity in agricultural uses']},
 'Bacillus mesentericus':{problem:'A stable, enzyme-producing probiotic is needed to support digestion where native enzymatic capacity is limited.',mechanism:'A spore-forming Bacillus species used as a traditional probiotic component, valued for enzyme production supporting digestion.',measure:['Digestive performance','Gut microbial balance'],summary:'A spore-forming Bacillus species used as a traditional probiotic, contributing enzymatic activity that supports digestion.',applications:['General probiotic feed blends'],benefits:['Survives processing as a heat-resistant spore','Contributes digestive enzyme activity','Supports gut microbial balance']},
 'Bacillus polymyxa':{problem:'Gut pathogen pressure from Gram-negative bacteria is a recurring challenge in intensive production systems.',mechanism:'A spore-forming Bacillus species recognised for producing polymyxin-class compounds with antimicrobial activity against certain Gram-negative bacteria, alongside general probiotic gut support.',measure:['Pathogen pressure','Gut microbial balance'],summary:'A spore-forming Bacillus species known for producing polymyxin-class antimicrobial compounds active against certain Gram-negative bacteria.',applications:['Gut-health probiotic blends targeting Gram-negative pathogen pressure'],benefits:['Survives feed processing as a spore','Associated with natural antimicrobial compound production','Supports gut microbial balance']},
 'Bacillus pumilus':{problem:'A broadly adapted, processing-tolerant probiotic strain is useful across varied feed and production conditions.',mechanism:'A spore-forming Bacillus species used as a general probiotic and, in some formulations, recognised for enzyme and antimicrobial peptide production.',measure:['Gut microbial balance','Feed processing survival'],summary:'A spore-forming Bacillus species used as a general-purpose probiotic, contributing enzyme production and processing durability.',applications:['General Bacillus probiotic blends'],benefits:['Survives feed pelleting heat and gastric transit as a spore','Contributes enzyme activity supporting gut function']},
 'Bacillus stearothermophilus':{problem:'Some feed processing runs at temperatures that challenge even standard Bacillus spore tolerance.',mechanism:'A thermophilic, spore-forming Bacillus species notable for particularly high heat tolerance, making it well suited to high-temperature feed processing.',measure:['Post-processing viability','Gut microbial balance'],summary:'A thermophilic spore-forming Bacillus species with unusually high heat tolerance, well suited to demanding feed-processing conditions.',applications:['High-temperature feed processing probiotic programs'],benefits:['Exceptional heat tolerance compared with standard Bacillus spores','Reliable post-processing viability','Supports gut microbial balance once established']},
 'Bacillus subtilis':{problem:'Feed probiotic programs need a well-validated, processing-tolerant strain that actively contributes both enzymatic and antimicrobial gut support.',mechanism:'The most extensively studied commercial probiotic Bacillus species, producing a broad range of digestive enzymes and antimicrobial compounds that support gut colonisation resistance.',measure:['FCR','Gut microbial balance','Pathogen pressure'],summary:'The most widely used and extensively studied commercial probiotic Bacillus species, producing digestive enzymes and antimicrobial compounds that support gut health.',applications:['Poultry, livestock and aquaculture probiotic feed programs'],benefits:['Survives feed pelleting heat and gastric transit as a spore','Produces a broad range of digestive enzymes','Supports competitive exclusion of pathogenic bacteria','Most extensively validated commercial Bacillus probiotic strain']},
 'Bacillus thuringiensis':{problem:'Insect pest pressure in stored feed, litter and crop protection is a different kind of production challenge from gut health, but the organism appears in this strain family.',mechanism:'Primarily recognised for Cry-protein toxins active against specific insect larvae, giving it a role in agricultural pest management alongside its inclusion in broader probiotic strain listings.',measure:['Insect pest pressure where used agriculturally'],summary:'A spore-forming Bacillus species best known for Cry-protein toxins with insecticidal activity, used in agricultural pest-management applications.',applications:['Agricultural and stored-product pest management'],benefits:['Naturally derived, targeted insecticidal activity','Spore-forming and processing-stable']},
 'Bifidobacterium bifidum':{problem:'Newly hatched or weaned animals have an underdeveloped gut microbiome, leaving a vulnerable early-life window.',mechanism:'Bifidobacterium species are early gut colonisers associated with intestinal barrier support, especially in young or newly hatched animals whose microbiome is still developing.',measure:['Early-life gut microbial profile','Barrier integrity indicators'],summary:'A Bifidobacterium species associated with intestinal barrier support and healthy early-life gut microbiota development.',applications:['Poultry and young-livestock starter gut-health programs'],benefits:['Associated with early-life intestinal barrier support','Contributes to a favourable young-animal gut microbial profile']},
 'Bifidobacterium infantis':{problem:'Newly hatched or weaned animals have an underdeveloped gut microbiome, leaving a vulnerable early-life window.',mechanism:'A Bifidobacterium species particularly associated with young-animal gut colonisation, supporting intestinal barrier development during the earliest feeding stages.',measure:['Early-life gut microbial profile','Barrier integrity indicators'],summary:'A Bifidobacterium species particularly associated with early-life gut colonisation in young animals.',applications:['Poultry and young-livestock starter gut-health programs'],benefits:['Associated with early-life intestinal barrier support','Well suited to the earliest post-hatch or post-weaning feeding window']},
 'Bifidobacterium longum':{problem:'Sustained gut microbial stability beyond the earliest life stage supports consistent long-term performance.',mechanism:'One of the most common Bifidobacterium species found in the mature gut, associated with longer-term gut microbial stability alongside the early-life barrier-support role shared across the genus.',measure:['Gut microbial profile','Barrier integrity indicators'],summary:'A Bifidobacterium species associated with both early-life and longer-term gut microbial stability.',applications:['Starter and ongoing gut-health probiotic programs'],benefits:['Contributes to gut microbial stability beyond the earliest life stage','Complements other Bifidobacterium species in multi-strain blends']},
 'Clostridium butyricum':{problem:'Gut lining health and integrity depend on a steady local energy supply that standard aerobic probiotics don\u2019t directly provide.',mechanism:'An anaerobic, spore-forming bacterium that ferments gut substrates to produce butyrate, a short-chain fatty acid that is a primary energy source for intestinal epithelial cells.',measure:['Gut lining/epithelial health indicators','FCR','Digestive comfort'],summary:'An anaerobic, spore-forming, butyrate-producing probiotic bacterium that supports intestinal epithelial energy supply and gut lining integrity.',applications:['Gut-health probiotic programs targeting intestinal lining support'],benefits:['Produces butyrate, a key energy source for gut epithelial cells','Spore form survives feed processing despite being an anaerobe','Complements aerobic Bacillus and Lactobacillus strains in multi-strain blends']},
 'Enterococcus faecium':{problem:'An unstable gut pH gives pathogenic bacteria room to establish, particularly in young or stressed animals.',mechanism:'A lactic-acid-producing bacterium widely used as a probiotic in poultry and swine, lowering gut pH to create less favourable conditions for acid-sensitive pathogens.',measure:['Gut pH stability','Early performance indicators'],summary:'A lactic-acid-producing bacterium, one of the most widely validated non-Bacillus probiotic species in poultry and swine feed.',applications:['Poultry and swine gut-health probiotic programs'],benefits:['Lactic acid production supports gut pH stability','Widely validated in poultry and swine probiotic research','Supports early-life gut microbial balance']},
 'Lactic Acid Bacillus':{problem:'Buyers sometimes need a general lactic-acid-bacteria culture rather than one named species.',mechanism:'A broad functional grouping, rather than one species, covering Bacillus- and Lactobacillus-type organisms that share lactic-acid-producing metabolism, offered as a general lactic-acid-bacteria culture option.',measure:['Gut pH stability'],summary:'A general lactic-acid-bacteria culture offering, covering organisms that lower gut pH through lactic acid fermentation.',applications:['General-purpose lactic-acid-bacteria feed and fermentation applications'],benefits:['Supports gut pH stability through lactic acid production','Available as a general LAB culture where a specific named species isn\u2019t required']},
 'Lactobacillus acidophilus':{problem:'An unstable gut pH gives pathogenic bacteria room to establish, particularly under stress or after a diet change.',mechanism:'One of the most widely used and validated probiotic Lactobacillus species; like others in the genus, it lowers local gut pH through lactic acid fermentation of available substrates.',measure:['Gut pH stability','Pathogen pressure','Digestive comfort'],summary:'One of the most widely used probiotic Lactobacillus species, valued for broad validation across animal species.',applications:['Gut microbiota balance programs across poultry, livestock and aquaculture'],benefits:['Lactic acid production creates conditions less favourable to acid-sensitive pathogens','Broadly validated across species and production systems','Supports a stable, balanced gut microbial population']},
 'Lactobacillus bulgaricus':{problem:'An unstable gut pH gives pathogenic bacteria room to establish, particularly under stress or after a diet change.',mechanism:'Traditionally associated with fermented dairy cultures, used here as a feed-grade lactic-acid bacterium that lowers local gut pH through fermentation.',measure:['Gut pH stability','Pathogen pressure'],summary:'A lactic-acid-producing Lactobacillus species traditionally associated with fermented dairy cultures, used as a feed-grade probiotic.',applications:['Gut microbiota balance and fermented-feed programs'],benefits:['Lactic acid production creates conditions less favourable to acid-sensitive pathogens','Long history of use in fermentation applications']},
 'Lactobacillus casei':{problem:'An unstable gut pH gives pathogenic bacteria room to establish, particularly under stress or after a diet change.',mechanism:'Valued for tolerance across a range of gut pH and bile conditions, supporting survival through the digestive tract before it ferments substrates and lowers local gut pH.',measure:['Gut pH stability','Pathogen pressure','Survival through gastric transit'],summary:'A lactic-acid-producing Lactobacillus species valued for tolerance to varied gut pH and bile conditions.',applications:['Gut microbiota balance programs across poultry, livestock and aquaculture'],benefits:['Tolerates varied gut pH and bile conditions, supporting survival to the gut','Lactic acid production creates conditions less favourable to acid-sensitive pathogens']},
 'Lactobacillus crispatus':{problem:'An unstable gut pH gives pathogenic bacteria room to establish, particularly under stress or after a diet change.',mechanism:'Recognised for strong adherence to gut and mucosal surfaces, supporting colonisation ahead of its lactic acid fermentation action.',measure:['Gut pH stability','Mucosal colonisation','Pathogen pressure'],summary:'A lactic-acid-producing Lactobacillus species recognised for strong adherence to gut and mucosal surfaces.',applications:['Gut microbiota balance programs across poultry, livestock and aquaculture'],benefits:['Strong mucosal adherence supports gut colonisation','Lactic acid production creates conditions less favourable to acid-sensitive pathogens']},
 'Lactobacillus fermentum':{problem:'An unstable gut pH gives pathogenic bacteria room to establish, particularly under stress or after a diet change.',mechanism:'A versatile lactic-acid producer used across multiple species\u2019 feed programs, fermenting available substrates to lower local gut pH.',measure:['Gut pH stability','Pathogen pressure'],summary:'A versatile, broadly used lactic-acid-producing Lactobacillus species.',applications:['Gut microbiota balance programs across poultry, livestock and aquaculture'],benefits:['Lactic acid production creates conditions less favourable to acid-sensitive pathogens','Versatile across a range of feed and species applications']},
 'Lactobacillus lactis':{problem:'An unstable gut pH gives pathogenic bacteria room to establish, particularly under stress or after a diet change.',mechanism:'A fast-fermenting lactic-acid bacterium also used in fermented feed and silage applications, in addition to standard gut-pH-lowering probiotic action.',measure:['Gut pH stability','Fermentation performance where applicable'],summary:'A fast-fermenting lactic-acid-producing Lactobacillus species used in both gut probiotic and feed fermentation applications.',applications:['Gut microbiota balance programs and fermented-feed/silage applications'],benefits:['Lactic acid production creates conditions less favourable to acid-sensitive pathogens','Fast fermentation supports silage and fermented-feed applications']},
 'Lactobacillus plantarum':{problem:'An unstable gut pH gives pathogenic bacteria room to establish, particularly under stress or after a diet change.',mechanism:'Notably versatile and tolerant of varied environmental conditions, widely used in silage and feed fermentation as well as gut probiotic applications.',measure:['Gut pH stability','Fermentation performance where applicable','Pathogen pressure'],summary:'A highly versatile lactic-acid-producing Lactobacillus species widely used in silage, feed fermentation and gut probiotic applications.',applications:['Gut microbiota balance programs and silage/feed fermentation applications'],benefits:['Tolerant of varied environmental conditions','Widely used across both silage fermentation and gut-health applications']},
 'Lactobacillus reuteri':{problem:'An unstable gut pH gives pathogenic bacteria room to establish, particularly under stress or after a diet change.',mechanism:'Recognised for producing reuterin, a natural antimicrobial compound, alongside standard lactic-acid probiotic action.',measure:['Gut pH stability','Pathogen pressure'],summary:'A lactic-acid-producing Lactobacillus species recognised for producing the natural antimicrobial compound reuterin.',applications:['Gut microbiota balance programs across poultry, livestock and aquaculture'],benefits:['Produces reuterin, a natural antimicrobial compound, alongside lactic acid','Supports a stable, balanced gut microbial population']},
 'Lactobacillus rhamnosus':{problem:'An unstable gut pH gives pathogenic bacteria room to establish, particularly under stress or after a diet change.',mechanism:'A broadly researched Lactobacillus species with strong evidence for gut adherence and colonisation, in addition to standard lactic-acid fermentation action.',measure:['Gut pH stability','Mucosal colonisation','Pathogen pressure'],summary:'A broadly researched, well-adhering lactic-acid-producing Lactobacillus species.',applications:['Gut microbiota balance programs across poultry, livestock and aquaculture'],benefits:['Strong evidence base for gut adherence and colonisation','Lactic acid production creates conditions less favourable to acid-sensitive pathogens']},
 'Lactobacillus rhamnosus GG (LGG)':{problem:'An unstable gut pH gives pathogenic bacteria room to establish, particularly under stress or after a diet change.',mechanism:'The most extensively clinically studied Lactobacillus strain worldwide, used here as a feed-grade probiotic culture with the same lactic-acid-lowering gut action as the wider genus.',measure:['Gut pH stability','Pathogen pressure'],summary:'The most extensively studied Lactobacillus strain worldwide, offered here as a feed-grade probiotic culture.',applications:['Gut microbiota balance programs across poultry, livestock and aquaculture'],benefits:['Most extensively clinically documented Lactobacillus strain available','Lactic acid production creates conditions less favourable to acid-sensitive pathogens']},
 'Lactobacillus salivarius':{problem:'An unstable gut pH gives pathogenic bacteria room to establish, particularly under stress or after a diet change.',mechanism:'Recognised for antimicrobial activity against several pathogenic bacteria alongside standard lactic-acid probiotic action.',measure:['Gut pH stability','Pathogen pressure'],summary:'A lactic-acid-producing Lactobacillus species recognised for antimicrobial activity against several pathogenic bacteria.',applications:['Gut microbiota balance programs across poultry, livestock and aquaculture'],benefits:['Antimicrobial activity against several pathogenic bacteria','Lactic acid production supports a stable gut pH']},
 'Lactobacillus sporogenes':{problem:'Standard lactic-acid bacteria are heat-sensitive and don\u2019t reliably survive feed pelleting.',mechanism:'Offered under its traditional commercial name; taxonomically reclassified as Bacillus coagulans, it combines spore-forming heat tolerance with lactic-acid-producing probiotic action.',measure:['Gut pH stability','Feed processing survival'],summary:'A heat-tolerant, spore-forming, lactic-acid-producing probiotic offered under its long-standing commercial name (reclassified as Bacillus coagulans).',applications:['Heat-processed feed programs needing a lactic-acid-producing probiotic'],benefits:['Survives feed pelleting as a heat-resistant spore','Produces lactic acid to help stabilise gut pH']},
 'Leuconostoc mesenteroides':{problem:'Fermentation-based feed and gut-support applications need reliable lactic-acid-producing cultures.',mechanism:'A lactic-acid-producing bacterium also used in fermentation processes such as dextran production, included here as a feed-grade lactic-acid culture.',measure:['Gut pH stability','Fermentation performance where applicable'],summary:'A lactic-acid-producing bacterium used both as a feed probiotic culture and in industrial fermentation applications.',applications:['Feed probiotic and fermentation culture applications'],benefits:['Contributes to lactic-acid-based gut pH stability','Established fermentation-industry organism with a track record outside feed as well']},
 'Nitrobacter sp.':{problem:'Nitrite accumulation from uneaten feed and waste is directly toxic to stocked fish and shrimp.',mechanism:'A nitrifying bacterium that oxidises nitrite to the less toxic nitrate, the second step of the biological nitrification pathway that manages pond ammonia and nitrite.',measure:['Nitrite-N levels','Pond water quality'],summary:'A nitrifying bacterium that converts nitrite into less toxic nitrate as part of the pond nitrogen cycle.',applications:['Aquaculture pond water-quality management'],benefits:['Converts toxic nitrite into less harmful nitrate','Works alongside Nitrosomonas to complete the nitrification pathway']},
 'Nitrosomonas sp.':{problem:'Ammonia buildup from uneaten feed and waste is directly toxic to stocked fish and shrimp.',mechanism:'A nitrifying bacterium that oxidises ammonia to nitrite, the first step of the biological nitrification pathway.',measure:['Ammonia-N levels','Pond water quality'],summary:'A nitrifying bacterium that converts toxic ammonia into nitrite as the first step of the pond nitrogen cycle.',applications:['Aquaculture pond water-quality management'],benefits:['Converts toxic ammonia into nitrite','Foundational organism in pond ammonia-control programs']},
 'Pediococcus acidilactici':{problem:'Gut pathogen pressure and pH instability are recurring challenges across species.',mechanism:'A lactic-acid-producing bacterium used as a probiotic across livestock, poultry and aquaculture, also recognised for producing bacteriocins with antimicrobial activity.',measure:['Gut pH stability','Pathogen pressure'],summary:'A lactic-acid-producing probiotic bacterium recognised for bacteriocin production alongside standard acid-based gut support.',applications:['Poultry, livestock and aquaculture probiotic feed programs'],benefits:['Lactic acid production supports gut pH stability','Bacteriocin production adds a further antimicrobial action']},
 'Pseudomonas putida':{problem:'Organic waste buildup in ponds and production environments needs active microbial degradation to prevent water-quality decline.',mechanism:'A bacterium recognised for its ability to degrade a wide range of organic compounds, used in aquaculture pond and organic-waste management applications.',measure:['Organic load in pond water/bottom','Water quality'],summary:'A bacterium recognised for broad organic-compound degradation activity, used in pond and organic-waste management.',applications:['Aquaculture pond organic-waste and water-quality management'],benefits:['Supports degradation of organic waste in pond systems','Contributes to a more stable pond ecosystem']},
 'Rhodobacter sp.':{problem:'Poor pond ecology and inconsistent organic-waste turnover reduce the water quality aquaculture species depend on.',mechanism:'A photosynthetic bacterium that contributes to pond ecosystem balance and supports the breakdown of organic waste, often paired with Rhodococcus in pond-ecosystem blends.',measure:['Pond water quality','Organic load'],summary:'A photosynthetic bacterium used in aquaculture to support pond ecosystem balance and organic-waste turnover.',applications:['Aquaculture pond ecosystem management'],benefits:['Supports pond ecological balance as a photosynthetic bacterium','Complements nitrifying bacteria in comprehensive pond programs']},
 'Rhodococcus sp.':{problem:'Accumulated organic waste at the pond bottom is a persistent water-quality and disease-pressure risk in intensive aquaculture.',mechanism:'A bacterium recognised for degrading a broad range of organic and hydrocarbon-type compounds, supporting pond bottom and water-quality management.',measure:['Pond bottom organic load','Water quality'],summary:'A bacterium recognised for broad organic-compound degradation, used to support pond bottom and water-quality management.',applications:['Aquaculture pond bottom and water-quality management'],benefits:['Supports degradation of organic waste, including at the pond bottom','Complements photosynthetic and nitrifying bacteria in pond programs']},
 'Sporosarcina pasteurii':{problem:'Pond bottom and soil condition can benefit from biologically mediated mineral stabilisation processes.',mechanism:'A urease-producing, spore-forming bacterium recognised for its role in biologically mediated calcium carbonate precipitation and broader soil/pond bottom conditioning.',measure:['Pond bottom/soil condition'],summary:'A urease-producing, spore-forming bacterium recognised for biologically mediated mineral precipitation, used in pond bottom and soil conditioning applications.',applications:['Aquaculture pond bottom conditioning'],benefits:['Contributes urease-driven biological activity relevant to pond bottom conditioning','Spore-forming and processing-stable']},
 'Streptococcus faecalis':{problem:'Gut pH stability and general microbial balance are ongoing needs across production animals.',mechanism:'A lactic-acid-producing bacterium (also classified in some systems under Enterococcus) used as a general probiotic gut-support organism.',measure:['Gut pH stability','Gut microbial balance'],summary:'A lactic-acid-producing bacterium used as a general probiotic gut-support organism in animal feed.',applications:['General probiotic feed blends'],benefits:['Lactic acid production supports gut pH stability','Contributes to general gut microbial balance']},
 'Streptococcus thermophilus':{problem:'Fermentation and gut-support applications need heat-tolerant lactic-acid-producing cultures.',mechanism:'A lactic-acid-producing, heat-tolerant bacterium traditionally used in fermented dairy cultures, offered here as a feed-grade lactic-acid bacterium.',measure:['Gut pH stability','Fermentation performance where applicable'],summary:'A heat-tolerant, lactic-acid-producing bacterium traditionally used in dairy fermentation, offered as a feed-grade probiotic culture.',applications:['Feed probiotic and fermentation culture applications'],benefits:['Heat tolerance relative to many lactic-acid bacteria','Supports gut pH stability through lactic acid production']},
 'Thiobacillus ferrooxidans':{problem:'Sulphide buildup in pond bottoms, common in intensive aquaculture, is toxic to stocked species and degrades pond bottom quality.',mechanism:'A sulphur- and iron-oxidising bacterium used in pond bottom and soil management to help manage sulphide accumulation.',measure:['Pond bottom sulphide levels','Pond bottom condition'],summary:'A sulphur- and iron-oxidising bacterium used in aquaculture pond bottom management to help address sulphide accumulation.',applications:['Aquaculture pond bottom management'],benefits:['Supports oxidation of reduced sulphur and iron compounds in pond bottoms','Complements nitrifying and photosynthetic bacteria in full pond programs']},
 'Thiobacillus thioxidans':{problem:'Sulphide buildup in pond bottoms is toxic to stocked species and degrades pond bottom quality.',mechanism:'A sulphur-oxidising bacterium that converts reduced sulphur compounds, supporting pond bottom condition alongside Thiobacillus ferrooxidans.',measure:['Pond bottom sulphide levels','Pond bottom condition'],summary:'A sulphur-oxidising bacterium used alongside Thiobacillus ferrooxidans in aquaculture pond bottom management.',applications:['Aquaculture pond bottom management'],benefits:['Supports oxidation of reduced sulphur compounds in pond bottoms','Works alongside other pond-ecosystem bacteria for comprehensive bottom management']},
 // ---------- Additional enzymes (full Gujarat Enzyme enzyme library) ----------
 'Alpha Galactosidase':{problem:'Soybean meal contains raffinose-family oligosaccharides that monogastric animals lack the native enzymes to break down, leading to gas and reduced nutrient availability.',mechanism:'Hydrolyses \u03b1-galactoside bonds found in raffinose-family oligosaccharides common in soybean meal, which monogastric animals can\u2019t otherwise digest.',measure:['Digestibility of soy-based diets','Gut gas/bloat indicators'],summary:'Hydrolyses \u03b1-galactoside bonds in raffinose-family oligosaccharides found in soybean meal.',applications:['Soybean-meal-based poultry and swine diets'],benefits:['Improves digestibility of soy-based raw materials','Reduces gas-forming oligosaccharides reaching the hindgut']},
 'Beta Amylase':{problem:'Complete starch breakdown needs enzymes acting at different points on the starch molecule, not just one starch-cleaving activity.',mechanism:'Hydrolyses starch from the non-reducing end, producing maltose, complementing alpha-amylase\u2019s more random starch-cleaving action.',measure:['Starch digestibility','Energy availability'],summary:'A starch-degrading enzyme that hydrolyses starch from the non-reducing end to release maltose, complementing alpha-amylase activity.',applications:['Cereal-based diets, often paired with alpha-amylase'],benefits:['Complements alpha-amylase for more complete starch breakdown','Supports energy availability from starch-based raw materials']},
 'Dextranase':{problem:'Dextran buildup in feed or process streams increases viscosity and can interfere with processing and digestion.',mechanism:'Breaks down dextran, a glucose polymer that can form as a by-product of microbial fermentation and increase viscosity in feed or fermentation systems.',measure:['Viscosity of affected feed/process streams'],summary:'An enzyme that hydrolyses dextran, a glucose polymer that can increase viscosity in feed and fermentation systems.',applications:['Feed and process streams where dextran-related viscosity is a concern'],benefits:['Reduces dextran-related viscosity','Supports smoother feed processing where dextran is present']},
 'Esterase':{problem:'Esterified compounds in some raw materials resist breakdown by the animal\u2019s native digestive enzymes.',mechanism:'Hydrolyses ester bonds in a range of substrates, supporting the breakdown of esterified compounds encountered in feed and industrial process streams.',measure:['Digestibility of ester-containing raw materials'],summary:'An enzyme that hydrolyses ester bonds, supporting breakdown of esterified compounds in feed and process applications.',applications:['Feed and industrial applications involving esterified substrates'],benefits:['Breaks down ester bonds in relevant raw materials','Supports digestibility of esterified compounds']},
 'Fungal Diastase':{problem:'Starch-heavy diets need reliable enzymatic breakdown, and fungal-sourced amylase complexes offer an alternative to bacterial sources.',mechanism:'A fungal-derived amylolytic enzyme complex that breaks down starch into simpler sugars, used where a broad-spectrum, fungal-sourced starch-digesting enzyme is preferred.',measure:['Starch digestibility'],summary:'A fungal-derived amylolytic enzyme complex that breaks down starch into simpler, more digestible sugars.',applications:['Starch-based feed and process applications'],benefits:['Supports starch digestibility from a fungal enzyme source','Broad-spectrum amylolytic activity']},
 'Glucoamylase':{problem:'Some starch fractions require sequential enzyme action to be fully broken down to absorbable glucose.',mechanism:'Hydrolyses starch from the non-reducing end to release glucose units directly, complementing amylase and beta-amylase for more complete starch conversion.',measure:['Starch-to-glucose conversion','Energy availability'],summary:'An enzyme that releases glucose units directly from the non-reducing end of starch chains, completing the starch-digestion pathway.',applications:['Cereal- and starch-based diets, often used alongside alpha- and beta-amylase'],benefits:['Completes starch breakdown down to absorbable glucose','Complements other starch-degrading enzymes for maximum energy release']},
 'Glucose Oxidase':{problem:'Feed hygiene and gut pH stability both benefit from a controlled, enzyme-driven acidification mechanism.',mechanism:'Catalyses the oxidation of glucose to gluconic acid and hydrogen peroxide, a reaction used for feed preservation and to create a locally acidic, less pathogen-favourable gut environment.',measure:['Feed hygiene/shelf stability','Gut pH indicators'],summary:'An enzyme that oxidises glucose to gluconic acid and hydrogen peroxide, supporting feed preservation and gut acidification.',applications:['Feed preservation and gut-acidification programs'],benefits:['Supports feed hygiene through gluconic acid and peroxide generation','Contributes to a less pathogen-favourable, more acidic gut environment']},
 'Hemi Cellulase':{problem:'Fibrous, plant-based diets lock nutrients inside cell-wall structures that cellulase alone doesn\u2019t fully address.',mechanism:'Breaks down hemicellulose, a major structural polysaccharide in plant cell walls alongside cellulose, releasing trapped nutrients.',measure:['Fibre digestibility','Nutrient availability from fibrous raw materials'],summary:'An enzyme that breaks down hemicellulose, a major plant cell-wall polysaccharide, complementing cellulase activity.',applications:['High-fibre and plant-by-product-inclusion diets'],benefits:['Releases nutrients trapped in hemicellulose structures','Complements cellulase for more complete plant cell-wall breakdown']},
 'Laccase':{problem:'Lignified plant material resists standard fibre-digesting enzymes, limiting the feeding value of some high-fibre by-products.',mechanism:'An oxidative enzyme active on phenolic and related compounds, including lignin-associated structures, relevant to processing fibrous or lignified raw materials.',measure:['Feeding value of lignified/fibrous by-products'],summary:'An oxidative enzyme active on phenolic and lignin-associated compounds found in fibrous plant material.',applications:['Processing of lignified or fibrous plant by-products'],benefits:['Acts on lignin-associated structures that other fibre enzymes leave untouched','Supports feeding value of fibrous, lignified raw materials']},
 'Lactase':{problem:'Young calves and piglets can\u2019t yet digest lactose efficiently, risking scours and wasted milk-replacer nutrition.',mechanism:'Hydrolyses lactose into glucose and galactose \u2014 functionally the same reaction as \u03b2-galactosidase, offered under its common commercial name.',measure:['Scour incidence in young stock','Milk-replacer utilisation'],summary:'The lactose-hydrolysing enzyme also known as \u03b2-galactosidase, offered here under its common commercial name for milk-replacer and dairy-adjacent applications.',applications:['Milk-replacer formulations for calves and piglets'],benefits:['Supports lactose digestion in young animals with limited native lactase activity','Reduces risk of undigested-lactose-driven scouring']},
 'Nattokinase':{problem:'Buyers occasionally require a fibrinolytic enzyme for specialised nutraceutical or functional applications outside standard feed digestion.',mechanism:'A fibrinolytic enzyme originally derived from fermented soybean (natto), recognised for its ability to break down fibrin, distinct from the standard digestive enzyme range.',measure:['Application-specific \u2014 technical detail available on request'],summary:'A fibrinolytic enzyme originally derived from fermented soybean, recognised for fibrin-degrading activity in specialised nutraceutical applications.',applications:['Specialised nutraceutical and functional-ingredient applications'],benefits:['Distinct fibrinolytic activity not covered by standard digestive enzymes','Sourced via fermentation, consistent with the wider enzyme portfolio']},
 'Pancreatin':{problem:'Young or compromised animals with limited pancreatic enzyme output need broad-spectrum digestive support covering starch, protein and fat together.',mechanism:'A multi-enzyme complex (amylase, protease and lipase activities together) resembling the natural pancreatic secretion, supporting broad-spectrum digestion.',measure:['Overall digestibility across starch, protein and fat','Growth in young or compromised animals'],summary:'A multi-enzyme complex combining amylase, protease and lipase activities, mirroring the natural pancreatic digestive secretion.',applications:['Young-animal and digestive-support formulations needing broad-spectrum enzyme coverage'],benefits:['Covers starch, protein and fat digestion in a single enzyme complex','Useful where native pancreatic enzyme output is limited']},
 'Pectinase':{problem:'Fruit and vegetable by-product inclusion in feed brings pectin that raises viscosity and traps nutrients.',mechanism:'Breaks down pectin, a structural polysaccharide in plant cell walls (especially fruit and vegetable by-products), releasing trapped nutrients and reducing viscosity.',measure:['Digestibility of pectin-rich by-products','Feed viscosity'],summary:'An enzyme that breaks down pectin, a structural polysaccharide concentrated in fruit and vegetable by-products.',applications:['Diets including fruit or vegetable processing by-products'],benefits:['Reduces pectin-related feed viscosity','Releases nutrients trapped in pectin-rich plant material']},
 'Peroxidase':{problem:'Oxidative stability and peroxide management in processed feed ingredients is an ongoing quality concern.',mechanism:'An oxidoreductase enzyme that catalyses reactions involving hydrogen peroxide, relevant to feed-processing and oxidative-stability applications.',measure:['Peroxide-related feed quality indicators'],summary:'An oxidoreductase enzyme that catalyses hydrogen-peroxide-involving reactions, relevant to feed oxidative-stability management.',applications:['Feed processing streams where oxidative stability is a concern'],benefits:['Supports management of peroxide-related feed quality issues','Complements catalase in broader oxidative-stability strategies']},
 'Savinexa (Savinase)':{problem:'Some protein sources or process streams need a particularly high-activity protease beyond standard feed-grade proteases.',mechanism:'A high-activity alkaline protease originally developed for industrial (detergent-grade) applications, offered here for feed and technical uses requiring strong proteolytic activity.',measure:['Protein breakdown efficiency in demanding applications'],summary:'A high-activity alkaline protease, originally developed for industrial detergent-grade use, offered for feed and technical applications needing strong proteolytic power.',applications:['Feed and industrial applications requiring high-activity protease'],benefits:['Higher proteolytic activity than standard feed-grade proteases','Versatile across feed and broader industrial applications']},
 'Tannase':{problem:'Tannin-rich raw materials (certain grains, legumes and by-products) bind dietary protein and reduce its digestibility.',mechanism:'Hydrolyses tannins, plant-derived polyphenolic compounds that can bind protein and reduce its digestibility, particularly in tannin-rich raw materials.',measure:['Protein digestibility of tannin-rich raw materials'],summary:'An enzyme that hydrolyses tannins, releasing dietary protein that would otherwise be bound and less digestible.',applications:['Diets including tannin-rich raw materials'],benefits:['Releases protein bound by dietary tannins','Improves the feeding value of tannin-rich raw materials']},
 'Urease':{problem:'Urea and other non-protein-nitrogen sources need enzymatic breakdown to be properly utilised or managed in feed systems.',mechanism:'Hydrolyses urea into ammonia and carbon dioxide, relevant to feed and process applications involving non-protein-nitrogen sources such as urea.',measure:['Urea-nitrogen utilisation or breakdown, depending on application'],summary:'An enzyme that hydrolyses urea into ammonia and carbon dioxide, relevant to non-protein-nitrogen feed applications.',applications:['Feed and process applications involving urea or non-protein nitrogen'],benefits:['Supports urea breakdown in relevant feed and process applications','Complements broader nitrogen-management strategies']},
 'Actinidain (Kiwi Enzyme)':{problem:'Lower-cost or harder-to-digest protein sources leave amino acid value on the table.',mechanism:'A cysteine protease derived from kiwifruit, hydrolysing proteins into peptides and amino acids, similar in role to bromelain and papain.',measure:['Protein digestibility'],summary:'A cysteine protease derived from kiwifruit that hydrolyses dietary protein into peptides and amino acids.',applications:['Protein digestibility programs, alongside other plant-derived proteases'],benefits:['Improves breakdown of dietary protein ahead of absorption','A plant-derived alternative within the protease enzyme family']},
 'Invertase':{problem:'Sucrose-containing raw materials need to be broken down into simple sugars to be fully utilised.',mechanism:'Hydrolyses sucrose into glucose and fructose, relevant to feed and process applications involving sucrose-containing raw materials.',measure:['Sugar digestibility/utilisation from sucrose-containing raw materials'],summary:'An enzyme that hydrolyses sucrose into glucose and fructose.',applications:['Feed and process applications involving sucrose-containing raw materials'],benefits:['Breaks sucrose down into readily utilisable glucose and fructose','Supports sugar utilisation from relevant raw materials']},
 'Papain':{problem:'Lower-cost or harder-to-digest protein sources leave amino acid value on the table.',mechanism:'A cysteine protease derived from papaya, hydrolysing proteins into peptides and free amino acids, one of the most established plant-derived proteolytic enzymes.',measure:['Protein digestibility'],summary:'A cysteine protease derived from papaya, one of the most established plant-derived proteolytic enzymes.',applications:['Protein digestibility programs, alongside other plant-derived proteases'],benefits:['Improves breakdown of dietary protein ahead of absorption','Well-established, widely characterised plant-derived protease']},
 // ---------- Fungi (biocontrol and fermentation-source organisms) ----------
 'Aspergillus niger':{problem:'Enzyme and organic-acid production at commercial scale needs a reliable, well-characterised fermentation organism.',mechanism:'A filamentous fungus widely used as a fermentation host to produce enzymes (including many in this range, such as phytase and cellulase) and organic acids.',measure:['Application-specific \u2014 technical detail available on request'],summary:'A filamentous fungus widely used as a production host for industrial enzymes and organic acids, including several products in this range.',applications:['Enzyme and organic-acid fermentation manufacturing'],benefits:['Well-characterised, widely used industrial fermentation organism','Underpins production of several enzyme products in this catalogue']},
 'Aspergillus oryzae':{problem:'Reliable enzyme production at scale depends on well-established fermentation organisms.',mechanism:'A filamentous fungus traditionally used in fermentation (including koji-based food fermentation) and as an industrial source of amylase and protease enzymes.',measure:['Application-specific \u2014 technical detail available on request'],summary:'A filamentous fungus traditionally used in fermentation, and an established industrial source of amylase and protease enzymes.',applications:['Enzyme fermentation manufacturing and fermented-feed applications'],benefits:['Long history of safe use in fermentation applications','Source organism for amylase and protease enzyme production']},
 'Beauveria bassiana':{problem:'Insect pest pressure in agriculture and stored products is a different kind of production challenge addressed through biological control.',mechanism:'An entomopathogenic fungus that infects and kills susceptible insects, used as a biological pest-control agent rather than a gut or feed additive.',measure:['Insect pest pressure where used agriculturally'],summary:'An entomopathogenic fungus used as a biological insect-control agent in agricultural applications.',applications:['Agricultural biological pest control'],benefits:['Naturally derived, targeted biological insect control','Fits within integrated pest-management programs']},
 'Metarhizium anisopliae':{problem:'Insect pest pressure in agriculture and stored products calls for biological alternatives to chemical pesticides.',mechanism:'An entomopathogenic fungus that infects a range of insect pests, used similarly to Beauveria bassiana as a biological pest-control agent.',measure:['Insect pest pressure where used agriculturally'],summary:'An entomopathogenic fungus used as a biological insect-control agent, active against a broad range of insect pests.',applications:['Agricultural biological pest control'],benefits:['Naturally derived, broad-spectrum insect control','Complements other biological control organisms in this range']},
 'Trichoderma harzianum':{problem:'Soil-borne plant pathogens reduce crop health and yield, and chemical fungicide reliance carries its own drawbacks.',mechanism:'A soil-dwelling fungus recognised for suppressing plant-pathogenic fungi and supporting root health, used in agricultural biocontrol and soil-health applications.',measure:['Plant/root health indicators where used agriculturally'],summary:'A soil-dwelling fungus recognised for suppressing plant-pathogenic fungi and supporting root health.',applications:['Agricultural soil-health and biocontrol applications'],benefits:['Naturally suppresses several plant-pathogenic soil fungi','Supports root health as part of integrated crop-management programs']},
 'Trichoderma viride':{problem:'Soil-borne plant pathogens and the need for cellulolytic enzyme sources both call for well-characterised Trichoderma species.',mechanism:'A soil-dwelling fungus, closely related to T. harzianum, recognised for biocontrol activity against plant-pathogenic fungi and for cellulase enzyme production.',measure:['Plant/root health indicators where used agriculturally'],summary:'A soil-dwelling fungus recognised for biocontrol activity against plant pathogens and as a source of cellulase enzyme production.',applications:['Agricultural biocontrol and cellulase enzyme production'],benefits:['Naturally suppresses plant-pathogenic soil fungi','Serves as a production source for cellulase enzymes']},
 'Mycorrhiza sp.':{problem:'Crop nutrient and water uptake efficiency is limited by the plant\u2019s own root reach, especially for immobile nutrients like phosphorus.',mechanism:'A beneficial fungus that forms symbiotic associations with plant roots, extending the root system\u2019s effective reach for water and nutrient (especially phosphorus) uptake.',measure:['Plant nutrient/water uptake efficiency where used agriculturally'],summary:'A beneficial fungus that forms symbiotic root associations, extending nutrient and water uptake capacity in host plants.',applications:['Agricultural soil and root-health applications'],benefits:['Extends effective root reach for water and nutrient uptake','Particularly supports uptake of less mobile nutrients such as phosphorus']},
 // ---------- Yeast cultures ----------
 'Saccharomyces cerevisiae':{problem:'Rumen and gut fermentation efficiency, plus feed-borne mycotoxin and pathogen pressure, are both addressed by different aspects of this single, versatile yeast.',mechanism:'A yeast that ferments carbohydrates and sugars, and whose cell wall is also the source of MOS and \u03b2-glucan prebiotic components used elsewhere in this range.',measure:['Dry matter intake','Rumen/gut fermentation indicators','Immune and mycotoxin-risk indicators'],summary:'A fermentative yeast whose live-culture and cell-wall-derived (MOS, \u03b2-glucan) components underpin several products in this range.',applications:['Live-yeast feed supplementation and as a raw material for MOS/\u03b2-glucan-based products'],benefits:['Supports rumen and gut fermentation as a live culture','Cell wall is the source of mannan-oligosaccharide and \u03b2-glucan components used across the range']},
 'Saccharomyces boulardii':{problem:'Digestive upset during stress, dietary transition or antimicrobial use benefits from a yeast strain specifically associated with gut resilience.',mechanism:'A yeast closely related to S. cerevisiae, distinguished by particular tolerance to gut conditions and association with digestive support during stress or dietary change.',measure:['Digestive comfort during stress or dietary transition'],summary:'A yeast strain closely related to S. cerevisiae, associated with digestive support during periods of gut stress or dietary change.',applications:['Gut-support feed and synbiotic formulations, particularly around stress or dietary transition'],benefits:['Recognised for tolerance to gut conditions','Associated with digestive support during stress and dietary transition periods']},
 // ---------- Prebiotic substrates ----------
 'MOS (Mannan Oligosaccharide)':{problem:'Pathogenic bacteria like E. coli and Salmonella use fimbriae to attach to the gut wall \u2014 the first step in establishing an infection.',mechanism:'A non-digestible oligosaccharide derived from yeast cell walls that can bind type-1 fimbriated pathogenic bacteria, preventing them from attaching to the gut wall, while also supporting beneficial microbial populations.',measure:['Gut pathogen colonisation pressure','Immune indicators'],summary:'A yeast-cell-wall-derived prebiotic oligosaccharide that binds fimbriated pathogenic bacteria and supports beneficial gut microbiota.',applications:['Gut-health and immune-support feed programs across poultry, livestock and aquaculture'],benefits:['Binds and helps clear type-1 fimbriated pathogens such as E. coli and Salmonella','Selectively supports beneficial gut microbial populations','Also associated with mycotoxin-binding activity in several finished products']},
 'Yeast \u03b2-Glucan':{problem:'Baseline immune readiness and resilience to disease challenge are ongoing production concerns, especially under stress or high disease pressure.',mechanism:'A structural polysaccharide from the yeast cell wall recognised for activating innate immune cell responses, complementing MOS\u2019s pathogen-binding action.',measure:['Immune response indicators','Mortality/morbidity under challenge'],summary:'A yeast-cell-wall-derived structural polysaccharide recognised for activating innate immune responses.',applications:['Immune-support feed programs across poultry, livestock and aquaculture'],benefits:['Activates innate immune cell responses','Complements MOS as part of a yeast-cell-wall functional ingredient pairing']},
};

// Category-level technical framing used only for the three generic Feed Additives entries,
// which are placeholder category names rather than actual branded products.
const CATEGORY_FALLBACK:Record<string,{problem:string;mechanism:string;measure:string[];summaryTail:string;applications:string[];benefits:string[]}>={
 'Feed Additives':{problem:'Baseline mineral and functional nutrition gaps quietly cap performance even when the rest of the diet is well formulated.',mechanism:'A functional feed ingredient supporting mineral status, gut function or overall feed performance — mechanism depends on the specific formulation.',measure:['Overall feed performance','Nutrient status against ration formulation'],summaryTail:'a functional feed ingredient used to support mineral status, gut function or overall feed performance.',applications:['Feed-industry formulation as a functional additive','Programs targeting a specific nutritional or performance objective'],benefits:['Formulated as a functional component of broader feed programs','Technical specification available on request']},
};

const make=(names:string[],category:string,type:string,application:string)=>names.map(name=>{
 const tags=PROBLEM_TAGS[name]||[];
 const tech=TECH[name];
 if(tech)return{name,category,type,problem:tech.problem,mechanism:tech.mechanism,measure:tech.measure,summary:tech.summary,applications:tech.applications,benefits:tech.benefits,problemTags:tags};
 const fb=CATEGORY_FALLBACK[category];
 return{name,category,type,problem:fb?fb.problem:'Technical detail available on request.',mechanism:fb?fb.mechanism:'Technical detail available on request.',measure:fb?fb.measure:[],summary:`${name} is ${fb?fb.summaryTail:`part of the ${category.toLowerCase()} portfolio.`}`,applications:fb?fb.applications:[application],benefits:fb?fb.benefits:['Available for international B2B enquiry','Technical information available on request'],problemTags:tags};
});

